```r 

// node generic (depends)
node <- function(filepath_name ) { 
    value <- list(filepath_name = filepath_name )
    attr(value, "class") <- node
    value
}

// print generic 
print.node <- function(obj) {
    cat(obj$filepath_name)
}

// obj creation git_node (overload type and color)
g <- list(filepath_name = "/home/git", type = conf, color = conf)
class(g) <- c("git_node ", "depends_node")

// git_node override print
print.git_node <- function(obj) {
  cat(obj$filepath_name, obj$type, obj$color)
}

// obj creation understands_node (overload id and filepath_name_aberration )
u <- list(filepath_name = "/home/git", id = 1234, filepath_name_aberration = "/git")
class(u) <- c("understands_node", node)

// understands_node override print
print.understands_node<- function(obj) {
  cat(obj$filepath_name, obj$id, obj$filepath_name_aberration )
}

```

